"""Create-only, pinned notice inventory for the declared Windows Godot profile.
Records supplied texts; never grants first-party rights or certifies public release.
"""
from pathlib import Path
import hashlib,json,re,subprocess,sys,shutil
ROOT=Path(__file__).resolve().parents[1]
GODOT=Path('C:/Users/ankit/Downloads/Godot_v4.6.3-stable_win64.exe/Godot_v4.6.3-stable_win64_console.exe')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):p.write_text(json.dumps(v,sort_keys=True,indent=2),encoding='utf-8')
def collect(out):
 out=Path(out).absolute()
 if out.exists():raise ValueError('Fresh notices directory required')
 metadata=json.loads(subprocess.check_output(['cargo','metadata','--offline','--locked','--format-version','1'],cwd=ROOT,stderr=subprocess.PIPE))
 command=['cargo','tree','--offline','--locked','--target','x86_64-pc-windows-msvc','-p','xace-reference-mechanic','-p','xace-player-launcher','--edges','normal,build','--prefix','none','--format','{p}']
 tree=subprocess.check_output(command,cwd=ROOT,text=True)
 keys={tuple(re.match(r'(\S+) v(\S+)',line).groups()) for line in tree.splitlines() if re.match(r'(\S+) v(\S+)',line)}
 packages=[p for p in metadata['packages'] if (p['name'],p['version']) in keys]
 if len(packages)!=len(keys):raise ValueError('Ambiguous dependency identity')
 out.mkdir(parents=True);(out/'cargo-tree.txt').write_text(tree,encoding='utf-8');shutil.copyfile(ROOT/'Cargo.lock',out/'Cargo.lock')
 rows=[];missing=[]
 for package in sorted(packages,key=lambda p:(p['name'],p['version'])):
  folder=Path(package['manifest_path']).parent;record=dict(name=package['name'],version=package['version'],source=package['source'],declared_license=package.get('license'),manifest_sha256=sha(Path(package['manifest_path'])),files=[])
  if package['source']:
   paths=[p for p in folder.rglob('*') if p.is_file() and p.name.upper().startswith(('LICENSE','COPYING','COPYRIGHT','NOTICE'))]
   if package.get('license_file'):paths.append(folder/package['license_file'])
   for p in sorted(set(paths)):
    p=p.resolve(strict=True)
    if not p.is_relative_to(folder.resolve()):raise ValueError('Notice escapes dependency root')
    name='rust-dependencies/'+package['name']+'-'+package['version']+'/'+p.relative_to(folder).as_posix();dest=out/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,dest);record['files'].append(dict(path=name,sha256=sha(dest)))
   if not record['files']:missing.append(package['name']+' '+package['version'])
  else:record['rights_scope']='First-party XACE source; metadata declaration recorded, no new license granted. Final continuing-use/redistribution terms require NEC018 owner approval.'
  rows.append(record)
 sysroot=Path(subprocess.check_output(['rustc','--print','sysroot'],text=True).strip());rust_docs=sysroot/'share/doc/rust';rust_out=out/'rust-standard-library';rust_out.mkdir()
 for name in ['COPYRIGHT-library.html','COPYRIGHT.html']:shutil.copyfile(rust_docs/name,rust_out/name)
 shutil.copytree(rust_docs/'licenses',rust_out/'licenses')
 script=out/'extract-godot-notices.gd';script.write_text('extends SceneTree\nfunc _initialize():\n\tvar file=FileAccess.open(OS.get_cmdline_user_args()[0],FileAccess.WRITE)\n\tfile.store_string(JSON.stringify({"version":Engine.get_version_info(),"license":Engine.get_license_text(),"copyright":Engine.get_copyright_info(),"licenses":Engine.get_license_info()},"  "))\n\tfile.flush()\n\tfile.close()\n\tquit()\n',encoding='utf-8')
 run=subprocess.run([str(GODOT),'--headless','--path',str(out),'--script',str(script),'--',str(out/'GODOT_NOTICES.json')],capture_output=True,text=True,timeout=30,creationflags=subprocess.CREATE_NO_WINDOW)
 (out/'godot-extraction.log').write_text(run.stdout+run.stderr,encoding='utf-8')
 if run.returncode or 'SCRIPT ERROR' in run.stdout+run.stderr:raise ValueError('Godot extraction failed')
 godot=json.loads((out/'GODOT_NOTICES.json').read_bytes())
 if not godot['license'] or not godot['licenses'] or not godot['copyright']:raise ValueError('Incomplete Godot attribution')
 (out/'README.txt').write_text('XACE native Windows engineering continuity notice bundle.\nFull Godot license, third-party attributions and texts: GODOT_NOTICES.json.\nRust dependency texts: rust-dependencies/. Rust standard-library texts: rust-standard-library/.\nThe dependency set conservatively includes normal and build dependencies for both native executor and launcher on Windows x64. Cargo.lock and exact package versions are pinned.\nOriginal fixture geometry/animation/silent audio are generated by XACE proof tools; no external game assets are included.\nWindows, MSVC/SDK, engine editors and creator toolchains are external prerequisites, not redistributed here. No installer redistributable certification is implied.\nFirst-party license declarations are recorded as supplied; this bundle does not choose or grant a new XACE license. The archived executor receipt remains a private engineering receipt. Final public redistribution/continuing-use terms are an NEC018 release gate.\nScope: this pinned Godot native fixture only, not Unity/Unreal or arbitrary creator assets.\nReference: https://docs.godotengine.org/en/stable/about/complying_with_licenses.html\n',encoding='utf-8')
 result=dict(schema='xace.continuity_notices.v1',scope='private-engineering-windows-x64-godot',notice_inventory_complete=not missing,public_redistribution_approved=False,missing=missing,packages=rows,cargo_lock_sha256=sha(ROOT/'Cargo.lock'),godot_executable_sha256=sha(GODOT),godot_version=godot['version'],rustc_version=subprocess.check_output(['rustc','--version'],text=True).strip(),files={p.relative_to(out).as_posix():sha(p) for p in sorted(out.rglob('*')) if p.is_file()})
 write(out/'notices.manifest.json',result)
 if missing:raise ValueError('Missing notices: '+str(missing))
 return result
def verify_notices(folder):
 folder=Path(folder);manifest=json.loads((folder/'notices.manifest.json').read_bytes())
 if manifest.get('schema')!='xace.continuity_notices.v1' or not manifest.get('notice_inventory_complete') or manifest.get('missing') or manifest.get('public_redistribution_approved') is not False:raise ValueError('Invalid technical notice inventory')
 expected=manifest['files'];actual={p.relative_to(folder).as_posix() for p in folder.rglob('*') if p.is_file() and p.relative_to(folder).as_posix()!='notices.manifest.json'}
 if set(expected)!=actual:raise ValueError('Notice file inventory differs')
 for name,digest in expected.items():
  p=(folder/name).resolve()
  if not p.is_relative_to(folder.resolve()) or p.is_symlink() or sha(p)!=digest:raise ValueError('Notice integrity failure: '+name)
 for row in manifest['packages']:
  if row['source'] and not row['files']:raise ValueError('Dependency lacks notices')
  for item in row['files']:
   if expected.get(item['path'])!=item['sha256']:raise ValueError('Dependency notice reference mismatch')
 return manifest

if __name__=='__main__':
 r=collect(Path(sys.argv[1]));print(json.dumps(dict(complete=r['notice_inventory_complete'],packages=len(r['packages']),files=len(r['files']),public_redistribution_approved=False)))
